package com.mutations.hunterhistory;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(HunterRumourHistoryConfig.GROUP)
public interface HunterRumourHistoryConfig extends Config
{
    String GROUP = "hunterRumourHistory";

    @ConfigItem(
        keyName = "masterOnly",
        name = "Master rumours only",
        description = "Records completions as Master rumours with a 6,240 XP turn-in reward.",
        position = 0
    )
    default boolean masterOnly()
    {
        return true;
    }

    @ConfigItem(
        keyName = "chatConfirmation",
        name = "Chat confirmation",
        description = "Print a RuneLite chat message when a rumour is saved.",
        position = 1
    )
    default boolean chatConfirmation()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show recent rumours",
        description = "Shows your most recently completed rumours on the RuneLite game overlay.",
        position = 2
    )
    default boolean showOverlay()
    {
        return true;
    }

    @Range(min = 1, max = 10)
    @ConfigItem(
        keyName = "historyRows",
        name = "History rows",
        description = "Number of recent rumours shown on the overlay.",
        position = 3
    )
    default int historyRows()
    {
        return 5;
    }

    @ConfigItem(
        keyName = "showCompletionTime",
        name = "Show completion time",
        description = "Shows the completion time underneath each recent rumour.",
        position = 4
    )
    default boolean showCompletionTime()
    {
        return false;
    }
}

package com.mutations.hunterhistory;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class HunterRumourHistoryOverlay extends OverlayPanel
{
    private static final DateTimeFormatter TIME_FORMAT =
        DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());

    private final HunterRumourHistoryPlugin plugin;
    private final HunterRumourHistoryConfig config;

    @Inject
    public HunterRumourHistoryOverlay(HunterRumourHistoryPlugin plugin, HunterRumourHistoryConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay())
        {
            return null;
        }

        panelComponent.getChildren().add(
            TitleComponent.builder()
                .text("Hunter Rumours")
                .build()
        );

        int shown = 0;
        for (RumourHistoryEntry entry : plugin.getRecentHistory())
        {
            if (shown >= config.historyRows())
            {
                break;
            }

            panelComponent.getChildren().add(
                LineComponent.builder()
                    .left(entry.getRumourType().getShortName())
                    .right(entry.getCatches() + " catches")
                    .build()
            );

            if (config.showCompletionTime())
            {
                panelComponent.getChildren().add(
                    LineComponent.builder()
                        .left("  " + TIME_FORMAT.format(entry.getCompletedAt()))
                        .right("")
                        .build()
                );
            }

            shown++;
        }

        if (shown == 0)
        {
            panelComponent.getChildren().add(
                LineComponent.builder()
                    .left("No rumours logged yet")
                    .build()
            );
        }

        return super.render(graphics);
    }
}

package com.mutations.hunterhistory;

import com.google.inject.Provides;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.LocalDateTime;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Hunter Rumour History",
    description = "Saves Hunter Rumour completion history and catches to CSV",
    tags = {"hunter", "rumours", "rumors", "history", "tracker"}
)
public class HunterRumourHistoryPlugin extends Plugin
{
    private static final String COMPLETION_MESSAGE =
        "You find a rare piece of the creature! You should take it back to the Hunter Guild.";

    private static final int MASTER_TURN_IN_XP = 6240;
    private static final DateTimeFormatter CSV_TIME =
        DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss").withZone(ZoneId.systemDefault());

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private HunterRumourHistoryConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private HunterRumourHistoryOverlay overlay;

    private RumourType currentRumour = RumourType.UNKNOWN;
    private int catches;
    private int previousHunterXp = -1;
    private Instant rumourStartedAt;
    private final Deque<RumourHistoryEntry> recentHistory = new ArrayDeque<>();

    @Provides
    HunterRumourHistoryConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(HunterRumourHistoryConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        resetSessionXp();
        loadRecentHistory();
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        currentRumour = RumourType.UNKNOWN;
        catches = 0;
        previousHunterXp = -1;
        rumourStartedAt = null;
        recentHistory.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            resetSessionXp();
            loadRecentHistory();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        // The whistle produces a GAMEMESSAGE containing "Your current rumour target is ...".
        if (event.getType() == ChatMessageType.GAMEMESSAGE)
        {
            String standardized = Text.standardize(event.getMessage());

            if (standardized.contains("Your current rumour target is"))
            {
                setCurrentRumour(RumourType.fromText(standardized));
                return;
            }

            if (standardized.equalsIgnoreCase(COMPLETION_MESSAGE))
            {
                // Run at tick-end so a same-tick Hunter XP event is counted first.
                clientThread.invokeAtTickEnd(this::finishRumour);
                return;
            }
        }

        // Hunter-master assignment dialogue also names the target. Scanning DIALOG messages
        // lets the logger work without requiring a whistle check for the four tracked tasks.
        if (event.getType() == ChatMessageType.DIALOG)
        {
            RumourType mentioned = RumourType.fromText(Text.standardize(event.getMessage()));
            if (mentioned != RumourType.UNKNOWN)
            {
                setCurrentRumour(mentioned);
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() != Skill.HUNTER)
        {
            return;
        }

        int currentXp = event.getXp();
        if (previousHunterXp < 0)
        {
            previousHunterXp = currentXp;
            return;
        }

        int delta = currentXp - previousHunterXp;
        previousHunterXp = currentXp;

        if (currentRumour == RumourType.UNKNOWN || delta <= 0)
        {
            return;
        }

        // A single StatChanged event can contain more than one successful catch when
        // multiple traps resolve together (especially chinchompas). Count exact multiples
        // of the per-catch XP rather than requiring the delta to equal one catch.
        // Herbiboar trail inspection XP is intentionally ignored; only the final
        // Herbiboar XP drop is counted.
        int xpPerCatch = currentRumour.getXpPerCatch();
        if (xpPerCatch > 0 && delta % xpPerCatch == 0)
        {
            catches += delta / xpPerCatch;
        }
    }

    private void setCurrentRumour(RumourType rumour)
    {
        if (rumour == RumourType.UNKNOWN)
        {
            return;
        }

        if (rumour != currentRumour)
        {
            currentRumour = rumour;
            catches = 0;
            rumourStartedAt = Instant.now();
        }
    }

    private void finishRumour()
    {
        if (currentRumour == RumourType.UNKNOWN)
        {
            client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "Hunter History",
                "Rumour completed, but the target was unknown. Check the whistle once after assignment so it can be logged.",
                ""
            );
            return;
        }

        Instant completedAt = Instant.now();
        int taskXp = catches * currentRumour.getXpPerCatch();
        int turnInXp = config.masterOnly() ? MASTER_TURN_IN_XP : 0;
        int totalHunterXp = taskXp + turnInXp;
        long durationSeconds = rumourStartedAt == null ? 0 :
            Math.max(0, completedAt.getEpochSecond() - rumourStartedAt.getEpochSecond());

        try
        {
            appendCsv(completedAt, currentRumour, catches, taskXp, turnInXp, totalHunterXp, durationSeconds);
            addRecentHistory(new RumourHistoryEntry(completedAt, currentRumour, catches));

            if (config.chatConfirmation())
            {
                client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "Hunter History",
                    "Saved " + currentRumour.getDisplayName() + " — " + catches + " catches, " +
                        totalHunterXp + " Hunter XP.",
                    ""
                );
            }
        }
        catch (IOException ex)
        {
            client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "Hunter History",
                "Could not save Hunter Rumour history: " + ex.getMessage(),
                ""
            );
        }

        // The rare-piece message means the task is complete. Do not carry the old task/catch count
        // into the next assignment.
        currentRumour = RumourType.UNKNOWN;
        catches = 0;
        rumourStartedAt = null;
    }

    private void appendCsv(
        Instant completedAt,
        RumourType rumour,
        int catchCount,
        int taskHunterXp,
        int turnInXp,
        int totalHunterXp,
        long durationSeconds
    ) throws IOException
    {
        Path directory = RuneLite.RUNELITE_DIR.toPath().resolve("hunter-rumour-history");
        Files.createDirectories(directory);

        String player = client.getLocalPlayer() == null ? "unknown" : client.getLocalPlayer().getName();
        String safePlayer = player == null ? "unknown" : player.replaceAll("[^A-Za-z0-9 _-]", "_");
        Path csv = directory.resolve(safePlayer + "-rumours.csv");

        boolean newFile = !Files.exists(csv) || Files.size(csv) == 0;
        try (BufferedWriter writer = Files.newBufferedWriter(
            csv,
            StandardCharsets.UTF_8,
            StandardOpenOption.CREATE,
            StandardOpenOption.APPEND))
        {
            if (newFile)
            {
                writer.write("completed_at,player,tier,rumour_type,catches,hunter_xp_per_catch,task_hunter_xp,turn_in_xp,total_hunter_xp,duration_seconds");
                writer.newLine();
            }

            writer.write(csvEscape(CSV_TIME.format(completedAt)) + "," +
                csvEscape(player) + "," +
                csvEscape(config.masterOnly() ? "Master" : "Unknown") + "," +
                csvEscape(rumour.getDisplayName()) + "," +
                catchCount + "," +
                rumour.getXpPerCatch() + "," +
                taskHunterXp + "," +
                turnInXp + "," +
                totalHunterXp + "," +
                durationSeconds);
            writer.newLine();
        }
    }

    private String csvEscape(String value)
    {
        if (value == null)
        {
            return "";
        }
        return "\"" + value.replace("\"", "\"\"") + "\"";
    }

    public Iterable<RumourHistoryEntry> getRecentHistory()
    {
        return Collections.unmodifiableCollection(recentHistory);
    }

    private void addRecentHistory(RumourHistoryEntry entry)
    {
        recentHistory.addFirst(entry);
        while (recentHistory.size() > 10)
        {
            recentHistory.removeLast();
        }
    }

    private void loadRecentHistory()
    {
        recentHistory.clear();

        Path csv = getPlayerCsvPath();
        if (csv == null || !Files.exists(csv))
        {
            return;
        }

        List<RumourHistoryEntry> loaded = new ArrayList<>();
        try (BufferedReader reader = Files.newBufferedReader(csv, StandardCharsets.UTF_8))
        {
            String line;
            boolean header = true;
            while ((line = reader.readLine()) != null)
            {
                if (header)
                {
                    header = false;
                    continue;
                }

                List<String> columns = parseCsvLine(line);
                if (columns.size() < 5)
                {
                    continue;
                }

                RumourType rumour = RumourType.fromText(columns.get(3));
                if (rumour == RumourType.UNKNOWN)
                {
                    continue;
                }

                try
                {
                    Instant completedAt = LocalDateTime.parse(columns.get(0), DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
                        .atZone(ZoneId.systemDefault())
                        .toInstant();
                    int catchCount = Integer.parseInt(columns.get(4));
                    loaded.add(new RumourHistoryEntry(completedAt, rumour, catchCount));
                }
                catch (RuntimeException ignored)
                {
                    // Ignore malformed/old rows and keep loading the rest of the history.
                }
            }
        }
        catch (IOException ignored)
        {
            return;
        }

        for (int i = loaded.size() - 1; i >= 0 && recentHistory.size() < 10; i--)
        {
            recentHistory.addLast(loaded.get(i));
        }
    }

    private Path getPlayerCsvPath()
    {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
        {
            return null;
        }

        String player = client.getLocalPlayer().getName();
        String safePlayer = player.replaceAll("[^A-Za-z0-9 _-]", "_");
        return RuneLite.RUNELITE_DIR.toPath()
            .resolve("hunter-rumour-history")
            .resolve(safePlayer + "-rumours.csv");
    }

    private List<String> parseCsvLine(String line)
    {
        List<String> fields = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean quoted = false;

        for (int i = 0; i < line.length(); i++)
        {
            char c = line.charAt(i);
            if (c == '"')
            {
                if (quoted && i + 1 < line.length() && line.charAt(i + 1) == '"')
                {
                    current.append('"');
                    i++;
                }
                else
                {
                    quoted = !quoted;
                }
            }
            else if (c == ',' && !quoted)
            {
                fields.add(current.toString());
                current.setLength(0);
            }
            else
            {
                current.append(c);
            }
        }

        fields.add(current.toString());
        return fields;
    }

    private void resetSessionXp()
    {
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            previousHunterXp = client.getSkillExperience(Skill.HUNTER);
        }
        else
        {
            previousHunterXp = -1;
        }
    }
}

package com.mutations.hunterhistory;

import java.time.Instant;

public class RumourHistoryEntry
{
    private final Instant completedAt;
    private final RumourType rumourType;
    private final int catches;

    public RumourHistoryEntry(Instant completedAt, RumourType rumourType, int catches)
    {
        this.completedAt = completedAt;
        this.rumourType = rumourType;
        this.catches = catches;
    }

    public Instant getCompletedAt()
    {
        return completedAt;
    }

    public RumourType getRumourType()
    {
        return rumourType;
    }

    public int getCatches()
    {
        return catches;
    }
}

package com.mutations.hunterhistory;

import java.util.Locale;

public enum RumourType
{
    DASHING_KEBBIT("Dashing kebbit", 156),
    MOONLIGHT_ANTELOPE("Moonlight antelope", 450),
    HERBIBOAR("Herbiboar", 2461),
    RED_CHINCHOMPA("Red chinchompa", 265),
    UNKNOWN("Unknown", 0);

    private final String displayName;
    private final int xpPerCatch;

    RumourType(String displayName, int xpPerCatch)
    {
        this.displayName = displayName;
        this.xpPerCatch = xpPerCatch;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public int getXpPerCatch()
    {
        return xpPerCatch;
    }

    public String getShortName()
    {
        switch (this)
        {
            case DASHING_KEBBIT:
                return "Dashing kebbit";
            case MOONLIGHT_ANTELOPE:
                return "Moonlight antelope";
            case HERBIBOAR:
                return "Herbiboar";
            case RED_CHINCHOMPA:
                return "Red chin";
            default:
                return "Unknown";
        }
    }

    public static RumourType fromText(String text)
    {
        if (text == null)
        {
            return UNKNOWN;
        }

        String normalized = text.toLowerCase(Locale.ROOT);

        // RuneScape/UI text may refer to red chinchompas by the creature name
        // "carnivorous chinchompa" instead of the item/common rumour name.
        if (normalized.contains("red chinchompa") ||
            normalized.contains("red chinchompas") ||
            normalized.contains("carnivorous chinchompa") ||
            normalized.contains("carnivorous chinchompas"))
        {
            return RED_CHINCHOMPA;
        }

        for (RumourType type : values())
        {
            if (type != UNKNOWN && normalized.contains(type.displayName.toLowerCase(Locale.ROOT)))
            {
                return type;
            }
        }
        return UNKNOWN;
    }
}

package com.mutations.hunterhistory;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Development launcher used by the Gradle `run` task.
 * It loads Hunter Rumour History as a builtin external plugin and then starts RuneLite.
 */
public class HunterRumourHistoryPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(HunterRumourHistoryPlugin.class);
        RuneLite.main(args);
    }
}
